def _pair_key(name_a: str, type_a: str, name_b: str, type_b: str) -> str:
    """Order-independent key so (A,B) and (B,A) are the same pair."""
    a = f"{type_a}::{name_a.strip().lower()}"
    b = f"{type_b}::{name_b.strip().lower()}"
    return " | ".join(sorted([a, b]))

