def _table_to_text(table: list) -> str:
    """Convert table to readable text for embedding."""
    rows = []
    for row in table:
        if row:
            clean = [str(cell).strip() if cell else "" for cell in row]
            rows.append(" | ".join(clean))
    return "\n".join(rows)

