def fingerprint(filepath: str) -> str:
    """MD5 hash of file content — detects duplicates regardless of filename."""
    h = hashlib.md5()
    with open(filepath, "rb") as f:
        for chunk in iter(lambda: f.read(8192), b""):
            h.update(chunk)
    return h.hexdigest()

